  day13Sentence("reading-02", "短文朗讀", "短文朗讀", "佢先去買啲半肥瘦嘅豬肉，又買咗啲豬膶同埋番茄番去滾湯。", "keu5 xin1 heo3 mai5 di1 bun3 fei4 seo3 ge3 ju1 yug6 yeo6 mai5 zo2 di1 ju1 yen2 tung4 mai4 fan1 ke2 fan1 heo3 guen2 tong1", "她先去买了些半肥瘦的猪肉，又买了些猪肝和番茄回去滚汤。", ["短文朗讀"]),
  day13Sentence("reading-03", "短文朗讀", "短文朗讀", "呢隻湯好有益㗎，大人細路都啱飲。", "ni1 zeg3 tong1 hou2 yeo5 yig1 ga3 dai6 yen4 sei3 lou6 dou1 ngam1 yem2", "这种汤很有益，大人小孩都适合喝。", ["短文朗讀"]),
  day13Sentence("reading-04", "短文朗讀", "短文朗讀", "佢仲買咗啲新界嚟嘅青菜，貴係貴啲，但係貪佢新鮮吖嘛。", "keu5 zung6 mai5 zo2 di1 sen1 gai3 lei4 ge3 ceng1 coi3 guei3 hei6 guei3 di1 dan6 hei6 tam1 keu5 sen1 xin1 a1 ma3", "她还买了些新界来的青菜，贵是贵一点，但是图它新鲜嘛。", ["短文朗讀"]),
  day13Sentence("reading-05", "短文朗讀", "短文朗讀", "佢喺街市行咗半個鐘頭，就買咗卅呀文鬆啲嘅餸。", "keu5 hei2 gai1 xi5 hang4 zo2 bun3 go3 jung1 teo4 zeo6 mai5 zo2 sa1 a6 men1 sung1 di1 ge3 sung3", "她在菜市场逛了半个钟头，就买了三十多块钱的菜。", ["短文朗讀"]),
  day13Sentence("reading-06", "短文朗讀", "短文朗讀", "臨番屋企嗰陣又買啲生果。", "lem4 fan1 ug1 kei2 go2 zen6 yeo6 mai5 di1 sang1 guo2", "回家前又买些水果。", ["短文朗讀"]),
  day13Sentence("reading-07", "短文朗讀", "短文朗讀", "佢好鍾意食提子，特別係酸酸地嗰隻。", "keu5 hou2 zung1 yi3 xig6 tei4 ji2 deg6 bid6 hei6 xun1 xun1 dei2 go2 zeg3", "她很喜欢吃葡萄，特别是酸酸的那种。", ["短文朗讀"]),
  day13Sentence("reading-08", "短文朗讀", "短文朗讀", "佢買咗一揪細細揪嘅，十文咋。", "keu5 mai5 zo2 yed1 ceo1 sei3 sei3 ceo1 ge3 seb6 men1 ja3", "她买了一小串，十块而已。", ["短文朗讀"]),
  day13Sentence("reading-09", "短文朗讀", "短文朗讀", "阿新哥鍾意食橙，佢又同佢買咗六個。", "a3 sen1 go1 zung1 yi3 xig6 cang2 keu5 yeo6 tung4 keu5 mai5 zo2 lug6 go3", "阿新哥喜欢吃橙子，她又给他买了六个。", ["短文朗讀"]),
  day13Sentence("reading-10", "短文朗讀", "短文朗讀", "噉，買一次餸就使咗成五呀文有多嘞。", "gem2 mai5 yed1 qi3 sung3 zeo6 sei2 zo2 seng4 ng5 a6 men1 yeo5 do1 la3", "这样，买一次菜就花了五十多块。", ["短文朗讀"])
